#!/usr/bin/env node

/**
 * Fix Heading Hierarchy - Simple Approach
 * 
 * Final Correct Hierarchy:
 * H1: Tool title (auto-generated by app.js)
 * H2: Interface sections (Enter Your Text, Results, etc.)  
 * H3: SEO main section headings
 * H4: SEO subsections and FAQ questions
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const toolsDir = path.join(__dirname, '..', 'src', 'tools');
const toolDirs = fs.readdirSync(toolsDir, { withFileTypes: true })
  .filter(dirent => dirent.isDirectory())
  .map(dirent => dirent.name);

console.log('🔧 Final heading hierarchy fix...');

let totalChanges = 0;

toolDirs.forEach(toolSlug => {
  const indexPath = path.join(toolsDir, toolSlug, 'index.js');
  
  if (!fs.existsSync(indexPath)) {
    return;
  }
  
  let content = fs.readFileSync(indexPath, 'utf8');
  let changes = 0;
  
  // Find the seo-content section
  const seoContentIndex = content.indexOf('<div class="seo-content">');
  if (seoContentIndex === -1) {
    console.log(`⚠️  ${toolSlug}: No seo-content section found`);
    return;
  }
  
  // Split content at seo-content
  const beforeSeoContent = content.substring(0, seoContentIndex);
  let seoContentPart = content.substring(seoContentIndex);
  
  // In SEO content section:
  // 1. Main section headings should be H3
  // 2. FAQ questions and subsections should be H4
  
  // Fix main section headings (these should be H3)
  const mainSeoHeadings = [
    'What is the Word Counter Tool?',
    'How to Use the Word Counter',
    'What is a Unique Words Counter?',
    'Why is Word Count Important?',
    'Word Counter Use Cases',
    'Frequently Asked Questions',
    'Understanding the Case Converter',
    'How to Use Our Case Converter',
    'Convert Capital Letters to Lowercase Made Simple',
    'Upper Case Converter for Professional Formatting',
    'Lower Case Converter for Streamlined Text',
    'Sentence Case Converter for Natural Reading',
    'Change Text to Uppercase for Maximum Impact',
    'Case Converter and Your Workflow',
    'Understanding the Value Proposition Generator',
    'How to Use Our Value Proposition Generator',
    'Value Proposition Maker: Your Strategic Messaging Partner',
    'Crafting Powerful Messages with a Value Statement Generator',
    'Unique Value Proposition Generator: Stand Out From the Competition',
    'Value Proposition Generator and Your Business Workflow',
    'Understanding the Passive Voice Detector',
    'How to Use Our Passive Voice Detector',
    'Mastering the Passive Sentence Detector',
    'Benefits of Our Passive Voice Detector Free Tool',
    'Passive Voice Detector and Your Writing Workflow',
    'Understanding the Meeting Cost Calculator',
    'How to Use Our Meeting Cost Calculator',
    'Meeting Cost Counter: Real-Time Financial Awareness',
    'Meeting Time Cost Calculator for Strategic Planning',
    'Meeting Cost Calculator Timer: Optimizing Business Efficiency',
    'Meeting Cost Tracker: Long-Term Meeting ROI Analysis',
    'Meeting Cost Calculator and Your Business Workflow',
    'Understanding the PDF Metadata Editor',
    'How to Use Our PDF Metadata Editor',
    'PDF Metadata Viewer: Revealing Hidden Document Information',
    'Change Metadata PDF: Professional Document Control',
    'Change Metadata in PDF: Advanced Privacy Protection',
    'PDF Metadata Editor and Your Document Workflow',
    'Understanding the Meta Description Generator',
    'How to Use Our Meta Description Generator',
    'What is a Meta Description Creator and Why You Need One',
    'SEO Description Generator: Boosting Your Click-Through Rates',
    'Best Practices for Meta Description Optimization',
    'Advanced Meta Description Strategies',
    'Meta Description Generator and Your SEO Workflow',
    'Understanding the Recipe Scaler',
    'How to Use Our Recipe Scaler',
    'Recipe Scaler Online: The Digital Kitchen Assistant',
    'Scaling Down Recipes: Perfect Portions for Smaller Groups',
    'Advanced Recipe Scaling Techniques',
    'Unit Conversion and Measurement Precision',
    'Recipe Scaler and Your Cooking Workflow'
  ];
  
  // Fix all main section headings to H3
  mainSeoHeadings.forEach(heading => {
    const h4Pattern = new RegExp(`<h4>${heading.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}</h4>`, 'g');
    const h2Pattern = new RegExp(`<h2>${heading.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}</h2>`, 'g');
    
    if (h4Pattern.test(seoContentPart)) {
      seoContentPart = seoContentPart.replace(h4Pattern, `<h3>${heading}</h3>`);
      changes++;
    }
    if (h2Pattern.test(seoContentPart)) {
      seoContentPart = seoContentPart.replace(h2Pattern, `<h3>${heading}</h3>`);
      changes++;
    }
  });
  
  // All remaining H3 headings in SEO content should be H4 (FAQ questions, subsections)
  // This is safe because we already converted main sections to H3 above
  const h3InSeoContent = seoContentPart.match(/<h3>(?!.*(?:Understanding|How to Use|What is|Why is|Frequently Asked Questions|and Your.*Workflow))/g);
  if (h3InSeoContent) {
    seoContentPart = seoContentPart.replace(/<h3>(?!.*(?:Understanding|How to Use|What is the|Why is|Frequently Asked Questions|and Your.*Workflow))/g, '<h4>');
    seoContentPart = seoContentPart.replace(/<\/h3>/g, function(match, offset) {
      // Only replace </h3> that don't belong to main sections
      const beforeMatch = seoContentPart.substring(0, offset);
      const lastH3 = beforeMatch.lastIndexOf('<h3>');
      if (lastH3 !== -1) {
        const h3Content = seoContentPart.substring(lastH3 + 4, offset);
        const isMainSection = mainSeoHeadings.some(heading => h3Content.includes(heading));
        return isMainSection ? match : '</h4>';
      }
      return '</h4>';
    });
    changes += h3InSeoContent.length;
  }
  
  content = beforeSeoContent + seoContentPart;
  
  if (changes > 0) {
    fs.writeFileSync(indexPath, content, 'utf8');
    console.log(`✅ ${toolSlug}: ${changes} SEO headings fixed`);
    totalChanges += changes;
  }
});

console.log(`\n🎉 Final fix completed: ${totalChanges} changes`);